/// <summary>Verdict for a single check result row.</summary>
public enum HealthStatus
{
    Pass,
    Warn,
    Fail,
    Error,   // the check itself could not run (bad SQL, source unavailable, etc.)
    Skipped, // intentionally not evaluated
}

/// <summary>A declarative check, loaded from YAML config. One per row in a checks file.</summary>
public sealed class CheckDefinition
{
    public string Name { get; set; } = "";
    public string Domain { get; set; } = "";
    public string Category { get; set; } = "";          // freshness | reconciliation | quality | flow
    public string Severity { get; set; } = "warning";   // critical | warning | info
    public string? Description { get; set; }            // optional one-line blurb, surfaced as a tooltip in the dashboard
    public int? Order { get; set; }                     // display-order hint; lower = earlier. Orders checks within a family, and families within a category by the family's lowest. Unset sorts after ordered ones.
    public string? Breakdown { get; set; }              // label for the group dimension; non-null => grouped
    public List<MeasureSpec> Measures { get; set; } = [];
    public AssertSpec Assert { get; set; } = new();

    /// <summary>When set, every measure is expected to return (k, v) rows and the assert is evaluated per group.</summary>
    public bool Grouped => !string.IsNullOrWhiteSpace(Breakdown);
}

/// <summary>How to obtain one metric from one source. Scalar measures select <c>v</c>; grouped select <c>k, v</c>.</summary>
public sealed class MeasureSpec
{
    public string Key { get; set; } = "value";
    public string Source { get; set; } = "duckdb";       // duckdb | cosmos | sql | fileshare
    public string? Sql { get; set; }                     // duckdb / cosmos / sql
    public string? Path { get; set; }                    // fileshare (relative to configured base)
    public string? Database { get; set; }                // cosmos
    public string? Container { get; set; }               // cosmos
    public string ValueKind { get; set; } = "number";    // number | timestamp
}

/// <summary>The assertion applied to the measures. Fields are interpreted per <see cref="Type"/>.</summary>
public sealed class AssertSpec
{
    public string Type { get; set; } = "threshold";      // age | threshold | diff
    public string? Of { get; set; }                      // age/threshold: which measure key (defaults to first)
    public string? Left { get; set; }                    // diff: left measure key
    public string? Right { get; set; }                   // diff: right measure key
    public string? Max { get; set; }                     // age: duration ("26h"); threshold: numeric ceiling
    public string? Min { get; set; }                     // threshold: numeric floor
    public string? Warn { get; set; }                    // age: duration warn level (below Max)
    public double? Tolerance { get; set; }               // diff: absolute tolerance
    public double? TolerancePct { get; set; }            // diff: relative tolerance (% of right side)
}

/// <summary>One measured value: a number (counts/ratios) or a timestamp (freshness).</summary>
public sealed record MeasureCell(double? Number, DateTimeOffset? Timestamp);

/// <summary>The result of running one <see cref="MeasureSpec"/>: cells keyed by group ("" for scalar), or an error.</summary>
public sealed class MeasureOutcome
{

/// <summary>Runs check definitions against resolved sources and produces result rows.</summary>
public sealed class CheckRunner(SourceRegistry sources)
{
    public async Task<List<CheckResult>> RunAsync(
        IEnumerable<CheckDefinition> checks,
        string runId,
        Func<string, Task>? log = null,
        CancellationToken ct = default)
    {
        var all = new List<CheckResult>();

        foreach (var check in checks)
        {
            ct.ThrowIfCancellationRequested();

            var startedAt = DateTimeOffset.UtcNow;
            var sw = Stopwatch.StartNew();
            List<AssertOutcome> outcomes;

            try
            {
                var measures = new Dictionary<string, MeasureOutcome>();
                foreach (var spec in check.Measures)
                {
                    var source = sources.Resolve(spec.Source);
                    measures[spec.Key] = source is null
                        ? new MeasureOutcome { Error = $"Unknown source '{spec.Source}'." }
                        : await source.MeasureAsync(spec, check.Grouped, ct);
                }

                outcomes = AssertEvaluator.Evaluate(check, measures, DateTimeOffset.UtcNow);
            }
            catch (Exception ex)
            {
                outcomes = [new AssertOutcome(null, HealthStatus.Error, ex.Message, [])];
            }

            sw.Stop();

            foreach (var o in outcomes)
            {
                all.Add(new CheckResult
                {
                    RunId = runId,
                    CheckName = check.Name,
                    Domain = check.Domain,
                    Category = check.Category,
                    Severity = check.Severity,
                    Description = check.Description,
                    Order = check.Order,
                    BreakdownKey = o.GroupKey,
                    Status = o.Status,
                    Message = o.Message,
                    Metrics = o.Metrics,
                    StartedAtUtc = startedAt,
                    DurationMs = sw.ElapsedMilliseconds,
                });
            }

            if (log is not null)
            {
                var worst = Rollup(outcomes.Select(x => x.Status));
                await log($"[{worst}] {check.Name} — {outcomes.Count} result(s), {sw.ElapsedMilliseconds} ms");
            }
        }

        return all;
    }

    /// <summary>Worst status across a set (Fail/Error dominate, then Warn, Skipped, Pass).</summary>
    public static HealthStatus Rollup(IEnumerable<HealthStatus> statuses)
    {
        HealthStatus worst = HealthStatus.Pass;
        var worstRank = -1;
        foreach (var s in statuses)
        {
            var r = Rank(s);
            if (r > worstRank) { worstRank = r; worst = s; }
        }
        return worst;
    }

    public static int Rank(HealthStatus s) => s switch
    {
        HealthStatus.Fail => 4,
        HealthStatus.Error => 4,
        HealthStatus.Warn => 2,
        HealthStatus.Skipped => 1,
        _ => 0,
    };
}

public static List<AssertOutcome> Evaluate(CheckDefinition check, IReadOnlyDictionary<string, MeasureOutcome> measures, DateTimeOffset nowUtc)
{
    var errored = measures.Where(m => m.Value.Error is not null).ToList();
    if (errored.Count > 0)
        return [new AssertOutcome(null, HealthStatus.Error, string.Join("; ", errored.Select(e => $"{e.Key}: {e.Value.Error}")), [])];

    return check.Assert.Type.ToLowerInvariant() switch
    {
        "age" => EvalAge(check, measures, nowUtc),
        "threshold" => EvalThreshold(check, measures),
        "diff" => EvalDiff(check, measures),
        _ => [new AssertOutcome(null, HealthStatus.Error, $"Unknown assert type '{check.Assert.Type}'.", [])],
    };
}

private static HealthStatus Breach(string severity)
    => string.Equals(severity, "critical", StringComparison.OrdinalIgnoreCase) ? HealthStatus.Fail : HealthStatus.Warn;

private static MeasureOutcome Pick(IReadOnlyDictionary<string, MeasureOutcome> m, string? key)
    => key is not null && m.TryGetValue(key, out var byKey) ? byKey : m.Values.First();

private static string? Group(string key) => key == MeasureOutcome.ScalarKey ? null : key;

private static List<AssertOutcome> EvalAge(CheckDefinition c, IReadOnlyDictionary<string, MeasureOutcome> m, DateTimeOffset now)
{
    var src = Pick(m, c.Assert.Of);
    var max = DurationParser.Parse(c.Assert.Max ?? throw new FormatException($"Check '{c.Name}': age assert requires 'max'."));
    TimeSpan? warn = string.IsNullOrWhiteSpace(c.Assert.Warn) ? null : DurationParser.Parse(c.Assert.Warn);

    var results = new List<AssertOutcome>();
    foreach (var (key, cell) in src.Cells)
    {
        if (cell.Timestamp is null)
        {
            results.Add(new AssertOutcome(Group(key), HealthStatus.Error, "No timestamp for age assert (is the source empty?).", []));
            continue;
        }

        var age = now - cell.Timestamp.Value;
        var metrics = new Dictionary<string, double?> { ["ageHours"] = Math.Round(age.TotalHours, 2), ["maxHours"] = Math.Round(max.TotalHours, 2) };

        HealthStatus status;
        string msg;
        if (age < TimeSpan.Zero) { status = HealthStatus.Warn; msg = $"Newest value is {Fmt(age.Negate())} in the future — likely future-dated/bad rows; filter them in the measure SQL."; }
        else if (age > max) { status = Breach(c.Severity); msg = $"Stale: {Fmt(age)} old (max {Fmt(max)})."; }
        else if (warn is { } w && age > w) { status = HealthStatus.Warn; msg = $"Aging: {Fmt(age)} old (warn {Fmt(w)})."; }
        else { status = HealthStatus.Pass; msg = $"Fresh: {Fmt(age)} old."; }

        results.Add(new AssertOutcome(Group(key), status, msg, metrics));
    }

    if (results.Count == 0)
        results.Add(new AssertOutcome(null, HealthStatus.Error, "No rows returned for age measure.", []));
    return results;
}

private static List<AssertOutcome> EvalThreshold(CheckDefinition c, IReadOnlyDictionary<string, MeasureOutcome> m)
{
    var src = Pick(m, c.Assert.Of);
    var min = ParseNullableDouble(c.Assert.Min);
    var max = ParseNullableDouble(c.Assert.Max);

    var results = new List<AssertOutcome>();
    foreach (var (key, cell) in src.Cells)
    {
        var metrics = new Dictionary<string, double?> { ["value"] = cell.Number, ["min"] = min, ["max"] = max };
        if (cell.Number is not { } v)
        {
            results.Add(new AssertOutcome(Group(key), HealthStatus.Error, "No numeric value for threshold assert.", metrics));
            continue;
        }

        HealthStatus status;
        string msg;
        if (min is { } mn && v < mn) { status = Breach(c.Severity); msg = $"{v} below min {mn}."; }
        else if (max is { } mx && v > mx) { status = Breach(c.Severity); msg = $"{v} above max {mx}."; }
        else { status = HealthStatus.Pass; msg = $"{v} within range."; }

        results.Add(new AssertOutcome(Group(key), status, msg, metrics));
    }

    if (results.Count == 0)
        results.Add(new AssertOutcome(null, HealthStatus.Error, "No rows returned for threshold measure.", []));
    return results;
}

private static List<AssertOutcome> EvalDiff(CheckDefinition c, IReadOnlyDictionary<string, MeasureOutcome> m)
{
    var leftKey = c.Assert.Left ?? throw new FormatException($"Check '{c.Name}': diff assert requires 'left'.");
    var rightKey = c.Assert.Right ?? throw new FormatException($"Check '{c.Name}': diff assert requires 'right'.");
    if (!m.TryGetValue(leftKey, out var left) || !m.TryGetValue(rightKey, out var right))
        return [new AssertOutcome(null, HealthStatus.Error, $"diff assert needs measures '{leftKey}' and '{rightKey}'.", [])];

    var tolerance = c.Assert.Tolerance ?? 0;
    var tolerancePct = c.Assert.TolerancePct ?? 0;

    var keys = left.Cells.Keys.Union(right.Cells.Keys).Distinct().ToList();
    var results = new List<AssertOutcome>();
    foreach (var key in keys)
    {
        var l = left.Cells.GetValueOrDefault(key)?.Number ?? 0;
        var r = right.Cells.GetValueOrDefault(key)?.Number ?? 0;
        var diff = l - r;
        var absDiff = Math.Abs(diff);
        var withinPct = tolerancePct > 0 && absDiff <= Math.Abs(r) * tolerancePct / 100.0;
        var ok = absDiff <= tolerance || withinPct;

        var metrics = new Dictionary<string, double?> { ["left"] = l, ["right"] = r, ["diff"] = diff };
        var status = ok ? HealthStatus.Pass : Breach(c.Severity);
        var msg = ok ? $"Match (Δ {diff})." : $"Mismatch: {leftKey}={l} vs {rightKey}={r} (Δ {diff}).";
        results.Add(new AssertOutcome(Group(key), status, msg, metrics));
    }

    if (results.Count == 0)
        results.Add(new AssertOutcome(null, HealthStatus.Pass, "No keys to compare.", []));
    return results;
}

private static readonly IDeserializer Deserializer = new DeserializerBuilder()
    .WithNamingConvention(CamelCaseNamingConvention.Instance)
    .IgnoreUnmatchedProperties()
    .Build();

public static List<CheckDefinition> Load(string yamlText)
    => Deserializer.Deserialize<List<CheckDefinition>>(yamlText) ?? [];

public static List<CheckDefinition> LoadFile(string path)
    => Load(File.ReadAllText(path));

/// <summary>
/// Loads with the same tolerant runtime deserializer, then adds strict structural and semantic
/// diagnostics for authoring. Unknown properties are reported here without changing existing hosts'
/// runtime behaviour.
/// </summary>
public static AuthoringCheckPack LoadForAuthoring(string yamlText, IEnumerable<string>? registeredSources = null)
{
    List<CheckDefinition> checks;
    try
    {
        checks = Load(yamlText);
    }
    catch (YamlDotNet.Core.YamlException ex)
    {
        return new([], [new CheckDiagnostic(
            CheckDiagnosticSeverity.Error,
            "yaml_parse_error",
            "checks",
            "The YAML could not be parsed. Fix the syntax or field type at the reported location.",
            checked((int)ex.Start.Line + 1),
            checked((int)ex.Start.Column + 1))]);
    }
    catch (Exception ex)
    {
        return new([], [new CheckDiagnostic(
            CheckDiagnosticSeverity.Error,
            "yaml_parse_error",
            "checks",
            $"The YAML could not be loaded ({ex.GetType().Name}).")]);
    }

    var diagnostics = InspectProperties(yamlText);
    diagnostics.AddRange(CheckValidator.Validate(checks, registeredSources));
    return new(checks, diagnostics);

public sealed class DuckDbCheckSource : ICheckSource, ICheckSourceCatalog
{
    private readonly Func<string> connectionStringFactory;

    public string Name => "duckdb";

    /// <summary>Fixed connection string — a single static database file.</summary>
    public DuckDbCheckSource(string connectionString)
        : this(() => connectionString)
    {
    }

    /// <summary>
    /// Connection string resolved per measure — for hosts whose database path changes between
    /// runs (e.g. versioned read snapshots resolved latest-by-name). A factory failure (no
    /// snapshot published yet) surfaces as that measure's source error; the run still completes.
    /// </summary>
    public DuckDbCheckSource(Func<string> connectionStringFactory)
        => this.connectionStringFactory = connectionStringFactory;

    public Task<MeasureOutcome> MeasureAsync(MeasureSpec spec, bool grouped, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(spec.Sql))
            return Task.FromResult(new MeasureOutcome { Error = "duckdb measure requires 'sql'." });

        try
        {
            var cells = new Dictionary<string, MeasureCell>();
            var isTimestamp = string.Equals(spec.ValueKind, "timestamp", StringComparison.OrdinalIgnoreCase);

            using var connection = new DuckDBConnection(connectionStringFactory());
            connection.Open();

            using var cmd = connection.CreateCommand();
            cmd.CommandText = spec.Sql;
            using var reader = cmd.ExecuteReader();

            var vOrd = reader.GetOrdinal("v");
            int? kOrd = grouped ? reader.GetOrdinal("k") : null;

            while (reader.Read())
            {
                var key = kOrd is { } ko && !reader.IsDBNull(ko)
                    ? reader.GetValue(ko)?.ToString() ?? MeasureOutcome.ScalarKey
                    : MeasureOutcome.ScalarKey;

                MeasureCell cell;
                if (reader.IsDBNull(vOrd))
                    cell = new MeasureCell(null, null);
                else if (isTimestamp)
                    cell = new MeasureCell(null, new DateTimeOffset(DateTime.SpecifyKind(Convert.ToDateTime(reader.GetValue(vOrd)), DateTimeKind.Utc)));
                else
                    cell = new MeasureCell(Convert.ToDouble(reader.GetValue(vOrd)), null);

                cells[key] = cell;
            }

            return Task.FromResult(new MeasureOutcome { Cells = cells, AsOfUtc = DateTimeOffset.UtcNow });
        }
        catch (Exception ex)
        {
            return Task.FromResult(new MeasureOutcome { Error = ex.Message });
        }

public SqlCheckSource(
    string? connectionString,
    string? qualifier,
    int commandTimeoutSeconds = DefaultCommandTimeoutSeconds)
{
    if (commandTimeoutSeconds <= 0)
        throw new ArgumentOutOfRangeException(
            nameof(commandTimeoutSeconds),
            "SQL command timeout must be positive.");

    this.connectionString = connectionString;
    this.commandTimeoutSeconds = commandTimeoutSeconds;
    Name = SourceName.Compose("sql", qualifier);
}

public string Name { get; }

public async Task<MeasureOutcome> MeasureAsync(MeasureSpec spec, bool grouped, CancellationToken ct)
{
    if (string.IsNullOrWhiteSpace(connectionString))
        return new MeasureOutcome { Error = "SQL is not configured (read-only connection string missing)." };

    if (string.IsNullOrWhiteSpace(spec.Sql))
        return new MeasureOutcome { Error = "sql measure requires 'sql'." };

    try
    {
        var cells = new Dictionary<string, MeasureCell>();
        var isTimestamp = string.Equals(spec.ValueKind, "timestamp", StringComparison.OrdinalIgnoreCase);

        await using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync(ct);

        await using var cmd = connection.CreateCommand();
        cmd.CommandText = spec.Sql;
        cmd.CommandTimeout = commandTimeoutSeconds;
        await using var reader = await cmd.ExecuteReaderAsync(ct);

        var vOrd = reader.GetOrdinal("v");
        int? kOrd = grouped ? reader.GetOrdinal("k") : null;

        while (await reader.ReadAsync(ct))
        {
            var key = kOrd is { } ko && !await reader.IsDBNullAsync(ko, ct)
                ? reader.GetValue(ko)?.ToString() ?? MeasureOutcome.ScalarKey
                : MeasureOutcome.ScalarKey;

            MeasureCell cell;
            if (await reader.IsDBNullAsync(vOrd, ct))
                cell = new MeasureCell(null, null);
            else if (isTimestamp)
                cell = new MeasureCell(null, ToUtc(reader.GetValue(vOrd)));
            else
                cell = new MeasureCell(Convert.ToDouble(reader.GetValue(vOrd)), null);

            cells[key] = cell;
        }

        return new MeasureOutcome { Cells = cells, AsOfUtc = DateTimeOffset.UtcNow };
    }

public sealed class SourceRegistry
{
    private readonly Dictionary<string, ICheckSource> _sources;

    public SourceRegistry(IEnumerable<ICheckSource> sources)
    {
        _sources = new Dictionary<string, ICheckSource>(StringComparer.OrdinalIgnoreCase);

        // Not ToDictionary: its duplicate-key ArgumentException names the key but not what collided,
        // and the failure it reports — two sources registered under one name — is a wiring bug whose
        // whole diagnosis is "which two". Qualify one of them (see SourceName) if they are meant to
        // coexist. Throwing remains correct: last-one-wins would turn a loud startup failure into
        // permanently wrong check results.
        foreach (var source in sources)
        {
            if (!_sources.TryAdd(source.Name, source))
                throw new ArgumentException(
                    $"Two check sources are registered as '{source.Name}' " +
                    $"({_sources[source.Name].GetType().Name} and {source.GetType().Name}). " +
                    $"Give one a qualifier — e.g. '{source.Name}{SourceName.Separator}<name>' — so both can be addressed.",
                    nameof(sources));
        }
    }

    public ICheckSource? Resolve(string name) => _sources.GetValueOrDefault(name);

    /// <summary>Every registered name, for startup logging and diagnostics.</summary>
    public IReadOnlyCollection<string> Names => _sources.Keys;

    /// <summary>Every registered source, for host-aware metadata discovery.</summary>
    public IReadOnlyCollection<ICheckSource> Sources => _sources.Values;
}

public sealed class CosmosCheckSource(CosmosClient? client) : ICheckSource, ICheckSourceCatalog
{
    public string Name => "cosmos";

    public async Task<MeasureOutcome> MeasureAsync(MeasureSpec spec, bool grouped, CancellationToken ct)
    {
        if (client is null)
            return new MeasureOutcome { Error = "Cosmos is not configured (ConnectionStrings:CosmosDB missing)." };

        if (string.IsNullOrWhiteSpace(spec.Sql) || string.IsNullOrWhiteSpace(spec.Database) || string.IsNullOrWhiteSpace(spec.Container))
            return new MeasureOutcome { Error = "cosmos measure requires 'sql', 'database' and 'container'." };

        try
        {
            var container = client.GetContainer(spec.Database, spec.Container);
            var cells = new Dictionary<string, MeasureCell>();

            using var iterator = container.GetItemQueryIterator<JObject>(new QueryDefinition(spec.Sql));
            while (iterator.HasMoreResults)
            {
                var page = await iterator.ReadNextAsync(ct);
                foreach (var row in page)
                {
                    var key = grouped ? row["k"]?.ToString() ?? MeasureOutcome.ScalarKey : MeasureOutcome.ScalarKey;
                    var v = row["v"];
                    double? number = v is null || v.Type == JTokenType.Null ? null : v.Value<double?>();
                    cells[key] = new MeasureCell(number, null);
                }
            }

            return new MeasureOutcome { Cells = cells, AsOfUtc = DateTimeOffset.UtcNow };
        }
        catch (Exception ex)
        {
            return new MeasureOutcome { Error = ex.Message };
        }
    }

    if (string.IsNullOrWhiteSpace(spec.Path))
        return Error("fileshare measure requires 'path'.");

    try
    {
        var wantCount = string.Equals(spec.ValueKind, "count", StringComparison.OrdinalIgnoreCase);

        var path = spec.Path;
        var recursive = path.StartsWith("**/", StringComparison.Ordinal) || path.StartsWith("**\\", StringComparison.Ordinal);
        if (recursive)
            path = path[3..];

        var combined = Path.IsPathRooted(path) ? path : Path.Combine(basePath, path);
        var hasWildcard = combined.Contains('*') || combined.Contains('?');

        if (!hasWildcard)
        {
            if (!File.Exists(combined))
                return Error($"File not found: {combined}");
            return wantCount
                ? Scalar(new MeasureCell(1, null))
                : Scalar(new MeasureCell(null, MTime(combined)));
        }

        var dir = Path.GetDirectoryName(combined) ?? basePath;
        var pattern = Path.GetFileName(combined);
        if (!Directory.Exists(dir))
            return Error($"Directory not found: {dir}");

        var matches = Directory.GetFiles(dir, pattern, recursive ? SearchOption.AllDirectories : SearchOption.TopDirectoryOnly);

        // Count includes everything (that's the point of the conflict-copy detector).
        if (wantCount)
            return Scalar(new MeasureCell(matches.Length, null));

        // Freshness ignores file-sync conflict copies (stale duplicates) when a marker is configured.
        var canonical = string.IsNullOrEmpty(conflictCopyMarker)
            ? matches
            : matches.Where(f => !Path.GetFileName(f).Contains(conflictCopyMarker, StringComparison.OrdinalIgnoreCase)).ToArray();
        if (canonical.Length == 0)
            return Error($"No files match (excluding conflict copies): {combined}");

        if (grouped)
        {
            var cells = canonical.ToDictionary(
                f => Path.GetFileNameWithoutExtension(f),
                f => new MeasureCell(null, MTime(f)));
            return Task.FromResult(new MeasureOutcome { Cells = cells, AsOfUtc = DateTimeOffset.UtcNow });
        }

        return Scalar(new MeasureCell(null, canonical.Max(MTime)));
    }
    catch (Exception ex)
    {
        return Error(ex.Message);
    }
}

/// <summary>
/// Append-only, partitioned result sink: one file per (domain, date, run) under
/// <c>{root}/results/domain=&lt;d&gt;/date=&lt;yyyy-MM-dd&gt;/&lt;runId&gt;.jsonl</c>. Each writer owns its own
/// files, so multiple apps can write to the same share with no lock contention; the dashboard unions
/// them at read time. (Parquet can replace JSONL later without changing the layout.)
/// </summary>
public sealed class JsonlResultSink(string root)
{
    private static readonly JsonSerializerOptions Json = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Converters = { new JsonStringEnumConverter() },
    };

    public async Task WriteAsync(IEnumerable<CheckResult> results, string runId, DateTimeOffset runDateUtc, CancellationToken ct = default)
    {
        foreach (var byDomain in results.GroupBy(r => string.IsNullOrWhiteSpace(r.Domain) ? "unknown" : r.Domain))
        {
            var dir = Path.Combine(root, "results", $"domain={byDomain.Key}", $"date={runDateUtc:yyyy-MM-dd}");
            Directory.CreateDirectory(dir);

            var file = Path.Combine(dir, $"{runId}.jsonl");
            var lines = byDomain.Select(r => JsonSerializer.Serialize(r, Json));
            await File.WriteAllLinesAsync(file, lines, ct);
        }
    }

    public IReadOnlyList<CheckResult> ReadAll()
    {
        var dir = Path.Combine(root, "results");
        if (!Directory.Exists(dir))
            return [];

        var results = new List<CheckResult>();
        foreach (var file in Directory.EnumerateFiles(dir, "*.jsonl", SearchOption.AllDirectories))
            ReadInto(file, results);
        return results;
    }

    /// <summary>
    /// Like <see cref="ReadAll"/> but only the runs on or after <paramref name="since"/>. Uses the
    /// <c>date=&lt;yyyy-MM-dd&gt;</c> partition directories to skip older days without opening their files —
    /// the trends dashboard reads a bounded window every render, so it must not pay for all of history as it
    /// grows. The partition is whole-day granular, so a final <see cref="CheckResult.StartedAtUtc"/> filter
    /// trims the boundary day precisely.
    /// </summary>
    public IReadOnlyList<CheckResult> ReadSince(DateTimeOffset since)
    {
        var dir = Path.Combine(root, "results");
        if (!Directory.Exists(dir))
            return [];

        var sinceDate = since.UtcDateTime.Date;
        var results = new List<CheckResult>();
        foreach (var dateDir in Directory.EnumerateDirectories(dir, "date=*", SearchOption.AllDirectories))
        {
            // Skip whole days strictly before the window. An unparseable dir name (shouldn't happen) is kept,
            // not silently dropped — the StartedAtUtc filter below still bounds it correctly.
            if (TryParsePartitionDate(Path.GetFileName(dateDir), out var date) && date < sinceDate)
                continue;
            foreach (var file in Directory.EnumerateFiles(dateDir, "*.jsonl"))
                ReadInto(file, results);
        }
        return results.Where(r => r.StartedAtUtc >= since).ToList();
    }

    private void ReadInto(string file, List<CheckResult> results)
    {
        foreach (var line in File.ReadLines(file))
        {
            if (string.IsNullOrWhiteSpace(line))
                continue;
            var parsed = JsonSerializer.Deserialize<CheckResult>(line, Json);
            if (parsed is not null)
                results.Add(parsed);
        }
    }

    private static bool TryParsePartitionDate(string dirName, out DateTime date)
    {
        const string prefix = "date=";
        date = default;
        return dirName.StartsWith(prefix, StringComparison.Ordinal)
            && DateTime.TryParseExact(dirName[prefix.Length..], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out date);
    }
}

